import {readJson,writeJson,deploymentRoot} from './classic/scripts/local-production/common.mjs';
import {join} from 'node:path';
const c=await readJson(join(deploymentRoot,'candidate.json'));
if(c.id!=='2026-10-28T05-01-29-249Z-7f86ffec') throw Error('Unexpected candidate');
await writeJson(join(deploymentRoot,'previous.json'),await readJson(join(deploymentRoot,'current.json')));
await writeJson(join(deploymentRoot,'current.json'),c);
await writeJson('analysis/projects-export-2026-10-28/release.json',c);
console.log(c.id);
